<template><header class="header" dir="rtl"><button class="menu" @click="$emit('toggle-sidebar')" aria-label="باز کردن منو">☰</button><div class="header-title"><strong>کافه‌حجره</strong><span>مدیریت رستوران</span></div><div class="header-actions"><button class="theme" @click="$emit('toggle-theme')" :aria-label="isDarkMode ? 'حالت روشن' : 'حالت تیره'">{{ isDarkMode ? '☀' : '◐' }}</button><button class="overflow" @click="menuOpen = !menuOpen" aria-label="گزینه‌های بیشتر">⋮</button><div v-if="menuOpen" class="overflow-menu"><RouterLink v-if="auth.canAccessFinancials" to="/dashboard/expenses" @click="menuOpen=false">مدیریت هزینه‌ها</RouterLink><button @click="logout">خروج از حساب</button></div></div></header></template>
<script setup>import { ref } from 'vue'; import { RouterLink, useRouter } from 'vue-router'; import { useAuthStore } from '@/store/auth'; defineProps({ isDarkMode:Boolean }); defineEmits(['toggle-sidebar','toggle-theme']); const menuOpen=ref(false), router=useRouter(), auth=useAuthStore(); function logout(){auth.logout();router.push('/login')}</script>
<style scoped>.header{grid-area:header;position:sticky;top:0;z-index:50;height:72px;display:flex;align-items:center;gap:1rem;padding:0 1.25rem;background:var(--surface);border-bottom:1px solid var(--border)}.menu,.theme,.overflow{border:0;background:var(--surface-subtle);color:var(--text);border-radius:8px;width:38px;height:38px;font-size:1.1rem;cursor:pointer}.header-title{display:grid;gap:.1rem}.header-title strong{color:var(--primary)}.header-title span{font-size:.75rem;color:var(--muted)}.header-actions{position:relative;display:flex;gap:.5rem;margin-right:auto}.overflow-menu{position:absolute;top:44px;left:0;min-width:170px;background:var(--surface);border:1px solid var(--border);box-shadow:var(--shadow);border-radius:9px;padding:.4rem;display:grid}.overflow-menu>*{padding:.65rem;text-align:right;border:0;background:transparent;color:var(--text);text-decoration:none;font:inherit;cursor:pointer}.overflow-menu>*:hover{background:var(--surface-subtle)}@media(min-width:901px){.menu{display:none}}</style>
